-- Venue Live Guest "Kelahiran Bayi Perempuan". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara babygirl), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'babygirl', 'Kelahiran Bayi Perempuan', 'babygirl', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 154, 'center 38%',
  $t${"name":"Kelahiran Bayi Perempuan","orn":"diamond","ui":{"ivory":"#FFF6F7","white":"#FFFFFF","soft":"#F8D7E0","soft2":"#E9A3B8","accent":"#D9648A","deep":"#7A2E4A","ink":"#5E2A3E","mute":"#A5798A","line":"#F1D3DB","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFFAFB","ink":"#5E2A3E","accent":"#D9648A","gold":"#C9A24A","leaf":"#F8D7E0","hbg":"rgba(255,246,247,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(94,42,62,.9)","acc":"#F2D27A","on":"#5E2A3E"},"scr":{"wine":"#7A2E4A","veil":"255,246,247"}}$t$::jsonb
